detaileddescription.para:
True if the mutex was successfully taken, false otherwise. If false is returned, then errno is set with a hint about why the the mutex couldn't be taken

Example //Globalvariablesfortherobot'sodometry,whichtherestoftherobot's
//subsystemswillutilize
doubleodom_x=0.0;
doubleodom_y=0.0;
doubleodom_heading=0.0;

//Thismutexprotectstheodometrydata.Wheneverwereadorwritetothe
//odometrydata,weshouldmakecopiesintothelocalvariables,andread
//all3valuesatoncetoavoiderrors.
pros::RecursiveMutexodom_mutex;

voidodom_task(void*param){
while(true){
//Firstwefetchtheodomcoordinatesfromthepreviousiterationofthe
//odometrytask.Theseareputintolocalvariablessothatwecan
//keepthesizeofthecriticalsectionassmallaspossible.Thislets
//othertasksthatneedtousetheodometrydatarununtilweneedto
//updateitagain.
odom_mutex.take();
doublex_old=odom_x;
doubley_old=odom_y;
doubleheading_old=odom_heading;
odom_mutex.give();

doublex_new=0.0;
doubley_new=0.0;
doubleheading_new=0.0;

//---Calculatenewposefortherobothere---

//Nowthatwehavethenewpose,wecanupdatetheglobalvariables
odom_mutex.take();
odom_x=x_new;
odom_y=y_new;
odom_heading=heading_new;
odom_mutex.give();

delay(10);
}
}

voidchassis_task(void*param){
while(true){
//Herewecopythecurrentodomvaluesintolocalvariablessothat
//wecanusethemwithoutworryingabouttheodometrytaskchangingsay,
//theyvaluerightafterwe'vereadthex.Thisensuresourvaluesare
//sound.
odom_mutex.take();
doublecurrent_x=odom_x;
doublecurrent_y=odom_y;
doublecurrent_heading=odom_heading;
odom_mutex.give();

//----Movetherobotusingthecurrentlocationsgoeshere----

delay(10);
}
}

voidinitialize(){
odom_mutex=pros::RecursiveMutex();

pros::Taskodom_task(odom_task,"OdometryTask");
pros::Taskchassis_task(odom_task,"ChassisControlTask");
}
.

timeout



Time to wait before the mutex becomes available. A timeout of 0 can be used to poll the mutex. TIMEOUT_MAX can be used to block indefinitely.




True if the mutex was successfully taken, false otherwise. If false is returned, then errno is set with a hint about why the the mutex couldn't be taken.

