voidodom_task(void*param){
while(true){
//Firstwefetchtheodomcoordinatesfromthepreviousiterationofthe
//odometrytask.Theseareputintolocalvariablessothatwecan
//keepthesizeofthecriticalsectionassmallaspossible.Thislets
//othertasksthatneedtousetheodometrydatarununtilweneedto
//updateitagain.
odom_mutex.lock();
doublex_old=odom_x;
doubley_old=odom_y;
doubleheading_old=odom_heading;
odom_mutex.unlock();

doublex_new=0.0;
doubley_new=0.0;
doubleheading_new=0.0;

//---Calculatenewposefortherobothere---

//Nowthatwehavethenewpose,wecanupdatetheglobalvariables
odom_mutex.lock();
odom_x=x_new;
odom_y=y_new;
odom_heading=heading_new;
odom_mutex.unlock();

delay(10);
}
}

